import unittest


def compare(game, guess):
    return [abs(x - y) for x, y in zip(game, guess)]


class TestCompare(unittest.TestCase):

    def test_basic_case(self):
        self.assertEqual(compare([1, 2, 3, 4, 5, 1], [1, 1, 1, 1, 1, 1]),
                         [0, 1, 2, 3, 4, 0])

    def test_all_correct_guesses(self):
        self.assertEqual(compare([3, 5, 7], [3, 5, 7]), [0, 0, 0])

    def test_guess_lower_than_game(self):
        self.assertEqual(compare([10, 20, 30], [1, 2, 3]), [9, 18, 27])

    def test_guess_higher_than_game(self):
        self.assertEqual(compare([1, 2, 3], [10, 20, 30]), [9, 18, 27])

    def test_mixed_differences(self):
        self.assertEqual(compare([2, 8, 4], [5, 3, 9]), [3, 5, 5])

    def test_negative_numbers(self):
        self.assertEqual(compare([-1, -5, -10], [1, 5, 10]), [2, 10, 20])

    def test_single_element(self):
        self.assertEqual(compare([7], [3]), [4])

    def test_empty_lists(self):
        self.assertEqual(compare([], []), [])

    def test_result_is_non_negative(self):
        result = compare([1, 2, 3], [100, 0, -50])
        self.assertTrue(all(x >= 0 for x in result))

    def test_result_type_is_list(self):
        self.assertIsInstance(compare([1, 2], [3, 4]), list)

    def test_unequal_lengths_uses_shorter(self):
        self.assertEqual(compare([1, 2, 3, 4], [10, 20]), [9, 18])


if __name__ == "__main__":
    unittest.main()
